// ============================================================
// VALIDATE & PARSE incoming multipart/form-data
// ============================================================
const items = $input.all();
const body = items[0]?.json?.body || items[0]?.json || {};
const binary = items[0]?.binary || {};

// --- Extract text fields ---
const name = (body.name || '').trim();
const description = (body.description || '').trim();
const regularPrice = (body.regular_price || '').toString().trim();
const salePrice = (body.sale_price || '').toString().trim();
const sku = (body.sku || '').toString().trim();
const stockMode = (body.stock_mode || 'in_stock').trim();
const quantity = body.quantity ? parseInt(body.quantity) : null;
const galleryCount = parseInt(body.gallery_count) || 0;

// Parse categories (supports array, JSON string, or comma string)
let categories = [];
if (Array.isArray(body.categories)) {
  categories = body.categories;
} else if (typeof body.categories === 'string' && body.categories.trim() !== '') {
  try { categories = JSON.parse(body.categories); } catch(e) {
    categories = body.categories.split(',').map(c => c.trim()).filter(Boolean);
  }
}
if (!Array.isArray(categories)) categories = [categories];

// Parse tags (supports array, JSON string, or comma string)
let tags = [];
if (Array.isArray(body.tags)) {
  tags = body.tags;
} else if (typeof body.tags === 'string' && body.tags.trim() !== '') {
  try { tags = JSON.parse(body.tags); } catch(e) {
    tags = body.tags.split(',').map(t => t.trim()).filter(Boolean);
  }
}
if (!Array.isArray(tags)) tags = [tags];
tags = tags.map(t => typeof t === 'string' ? t.trim() : (t?.name || t)).filter(Boolean);

// Parse brand(s) — supports array ([12, 34]), JSON string ('[12, 34]'), comma string ('12, 34'), or single ID
let brandIds = [];
const rawBrand = body.brands || body.brand;

if (Array.isArray(rawBrand)) {
  brandIds = rawBrand.map(b => parseInt(b)).filter(id => !isNaN(id) && id > 0);
} else if (typeof rawBrand === 'string' && rawBrand.trim() !== '') {
  try {
    const parsed = JSON.parse(rawBrand);
    if (Array.isArray(parsed)) {
      brandIds = parsed.map(b => parseInt(b)).filter(id => !isNaN(id) && id > 0);
    } else if (!isNaN(parseInt(parsed)) && parseInt(parsed) > 0) {
      brandIds = [parseInt(parsed)];
    }
  } catch(e) {
    brandIds = rawBrand.split(',').map(b => parseInt(b.trim())).filter(id => !isNaN(id) && id > 0);
  }
} else if (typeof rawBrand === 'number' && rawBrand > 0) {
  brandIds = [rawBrand];
}

const brandId = brandIds.length > 0 ? brandIds[0] : null;

// --- Validation ---
const errors = [];

if (!name) errors.push('Product name is required.');
if (!description) errors.push('Description is required.');
if (!regularPrice || parseFloat(regularPrice) < 0) errors.push('Valid regular price is required.');

if (salePrice && parseFloat(salePrice) > parseFloat(regularPrice)) {
  errors.push('Sale price cannot exceed regular price.');
}

// Validate stock logic
if (stockMode === 'track_quantity') {
  if (quantity === null || quantity === undefined || isNaN(quantity)) {
    errors.push('Quantity is required when tracking stock.');
  } else if (!Number.isInteger(quantity) || quantity <= 0) {
    errors.push('Quantity must be a positive integer (>= 1).');
  }
}

// Check for main product image in binary data
if (!binary.product_image) {
  errors.push('Product image is required.');
}

if (errors.length > 0) {
  return [{
    json: {
      _valid: false,
      _error: {
        success: false,
        message: errors.join(' ')
      }
    }
  }];
}

// --- Build validated data object ---
return [{
  json: {
    _valid: true,
    _formData: {
      name,
      description,
      regularPrice,
      salePrice: salePrice || null,
      sku: sku || null,
      stockMode,
      quantity,
      categories,
      tags,
      brandId,
      brandIds,
      galleryCount
    }
  },
  binary: binary
}];

// Pass through validation error to the error response node
const items = $input.all();
return [{ json: items[0].json._error }];

// ============================================================
// PREPARE IMAGE UPLOAD ITEMS
// ============================================================
// Create one output item per image (main image first, then gallery).
// Each item carries the binary under a 'file' key and metadata.
// n8n will process all items through the next HTTP Request node.

const items = $input.all();
const binary = items[0].binary || {};
const formData = items[0].json._formData;
const galleryCount = formData.galleryCount || 0;

const outputItems = [];

// 1. Main product image (always first)
if (binary.product_image) {
  outputItems.push({
    json: {
      _imageType: 'main',
      _imageIndex: 0,
      _formData: formData
    },
    binary: {
      file: binary.product_image
    }
  });
}

// 2. Gallery images (indexed as gallery_image_0, gallery_image_1, etc.)
for (let i = 0; i < galleryCount; i++) {
  const key = `gallery_image_${i}`;
  if (binary[key]) {
    outputItems.push({
      json: {
        _imageType: 'gallery',
        _imageIndex: i + 1,
        _formData: formData
      },
      binary: {
        file: binary[key]
      }
    });
  }
}

return outputItems;

// ============================================================
// COLLECT ALL UPLOADED IMAGE IDs
// ============================================================
const uploadItems = $input.all();
const formData = $('Code - Validate Input').first().json._formData || {};

let mainImageId = null;
const galleryImageIds = [];

for (let i = 0; i < uploadItems.length; i++) {
  const data = uploadItems[i].json;
  const mediaId = data.id;

  if (!mediaId) {
    continue;
  }

  if (i === 0) {
    mainImageId = mediaId;
  } else {
    galleryImageIds.push(mediaId);
  }
}

if (!mainImageId) {
  return [{
    json: {
      _error: true,
      success: false,
      message: 'Failed to upload the main product image to WordPress Media: ' + (uploadItems[0]?.json?.message || 'Media upload error')
    }
  }];
}

// Build the images array for WooCommerce (main image first)
const wcImages = [{ id: mainImageId }];
galleryImageIds.forEach(gid => wcImages.push({ id: gid }));

// Prepare tag items if tags exist
const tags = formData.tags || [];

if (tags.length > 0) {
  return tags.map((tagName, idx) => ({
    json: {
      _tagName: tagName,
      _tagIndex: idx,
      _wcImages: wcImages,
      _hasTags: true
    }
  }));
} else {
  return [{
    json: {
      _wcImages: wcImages,
      _hasTags: false,
      _tagIds: []
    }
  }];
}

// ============================================================
// AGGREGATE TAG IDs (HANDLES NEW & PRE-EXISTING TAGS)
// ============================================================
const items = $input.all();
const tagIds = [];

for (const item of items) {
  const data = item.json || {};

  // Case 1: Tag was freshly created
  if (data.id) {
    tagIds.push(parseInt(data.id));
    continue;
  }

  // Case 2: Tag already existed (term_exists in data.data.resource_id)
  if (data.data?.resource_id) {
    tagIds.push(parseInt(data.data.resource_id));
    continue;
  }

  // Case 3: Tag already existed but wrapped in n8n/Axios error object
  const rawStr = JSON.stringify(data);
  const match = rawStr.match(/resource_id[^0-9]+(\d+)/i);
  if (match && match[1]) {
    tagIds.push(parseInt(match[1]));
  }
}

const wcImages = $('Code - Collect Image IDs & Prepare Tags').first().json._wcImages || [];

return [{
  json: {
    _wcImages: wcImages,
    _tagIds: tagIds
  }
}];

const wcImages = $('Code - Collect Image IDs & Prepare Tags').first().json._wcImages || [];
return [{
  json: {
    _wcImages: wcImages,
    _tagIds: []
  }
}];

// ============================================================
// BUILD WOOCOMMERCE PRODUCT PAYLOAD
// ============================================================
const formData = $('Code - Validate Input').first().json._formData || {};
const tagData = $input.first()?.json || {};
const wcImages = tagData._wcImages || $('Code - Collect Image IDs & Prepare Tags').first().json._wcImages || [];
const tagIds = tagData._tagIds || [];

// --- Base product payload ---
const product = {
  name: formData.name || 'Product',
  type: 'simple',
  description: formData.description || '',
  regular_price: (formData.regularPrice !== undefined && formData.regularPrice !== null) ? formData.regularPrice.toString() : '',
  images: wcImages
};

// --- Optional: Sale price ---
if (formData.salePrice && formData.salePrice !== '' && formData.salePrice !== null) {
  product.sale_price = formData.salePrice.toString();
}

// --- Optional: SKU ---
if (formData.sku && formData.sku !== '') {
  product.sku = formData.sku.toString();
}

// --- Categories ---
if (formData.categories && formData.categories.length > 0) {
  product.categories = formData.categories.map(id => ({ id: parseInt(id) }));
}

// --- Tags ---
if (tagIds.length > 0) {
  product.tags = tagIds.map(id => ({ id: parseInt(id) }));
}

// --- Stock logic ---
switch (formData.stockMode) {
  case 'in_stock':
    product.manage_stock = false;
    product.stock_status = 'instock';
    break;
  case 'out_of_stock':
    product.manage_stock = false;
    product.stock_status = 'outofstock';
    break;
  case 'track_quantity':
    product.manage_stock = true;
    if (formData.quantity !== null && formData.quantity !== undefined) {
      product.stock_quantity = parseInt(formData.quantity);
    }
    break;
  default:
    product.manage_stock = false;
    product.stock_status = 'instock';
}

return [{
  json: {
    _productPayload: product,
    _brandId: formData.brandId || null
  }
}];

// ============================================================
// PROCESS PRODUCT CREATION RESULT & PREPARE BRAND ASSIGNMENT
// ============================================================
const items = $input.all();
const data = items[0]?.json || {};
const formData = $('Code - Validate Input').first().json._formData || {};
const brandIds = formData.brandIds || (formData.brandId ? [formData.brandId] : []);

// Check if product was created successfully
if (!data.id) {
  return [{
    json: {
      _error: true,
      success: false,
      message: 'Failed to create product: ' + (data.message || JSON.stringify(data))
    }
  }];
}

return [{
  json: {
    _productId: data.id,
    _productName: data.name || formData.name || 'Product',
    _brandId: formData.brandId || (brandIds[0] || null),
    _brandIds: brandIds,
    _hasBrand: brandIds.length > 0,
    _productCreated: true
  }
}];

const createdProduct = $('HTTP Request - Create WooCommerce Product').first()?.json || {};

return [{
  json: {
    success: true,
    message: 'Product created successfully!',
    product: {
      id: createdProduct.id || null,
      name: createdProduct.name || 'Product',
      brand_assigned: true
    }
  }
}];

const createdProduct = $('HTTP Request - Create WooCommerce Product').first()?.json || {};

return [{
  json: {
    success: true,
    message: 'Product created successfully!',
    product: {
      id: createdProduct.id || null,
      name: createdProduct.name || 'Product',
      brand_assigned: false
    }
  }
}];
